// server/ai/adapter.ts
async function executeWebSearch(query) {
  try {
    const response = await fetch(
      `https://api.duckduckgo.com/?q=${encodeURIComponent(query)}&format=json&no_html=1&skip_disambig=1`,
      { signal: AbortSignal.timeout(8e3) }
    );
    if (!response.ok) return "";
    const data = await response.json();
    const results = [];
    if (data.AbstractText) results.push(data.AbstractText);
    if (data.Answer) results.push(`\u7B54\u6848: ${data.Answer}`);
    if (data.RelatedTopics && Array.isArray(data.RelatedTopics)) {
      for (const topic of data.RelatedTopics.slice(0, 3)) {
        if (topic.Text) results.push(topic.Text);
      }
    }
    if (results.length === 0) {
      return `\u641C\u7D22 "${query}" \u672A\u83B7\u53D6\u5230\u76F4\u63A5\u7ED3\u679C\uFF0C\u8BF7\u57FA\u4E8E\u5DF2\u77E5\u4FE1\u606F\u56DE\u7B54\u3002`;
    }
    return results.slice(0, 5).join("\n");
  } catch {
    return "";
  }
}
function quirksFor(provider, model) {
  const m = (model || "").toLowerCase();
  if (provider === "openai" && /^(gpt-6|gpt-5|o[1-9])/.test(m)) {
    return { tokenParam: "max_completion_tokens", dropTemperature: true };
  }
  if (provider === "qwen" && /^(qwen3|qwen-plus)/.test(m)) {
    return { extraBody: { enable_thinking: false } };
  }
  return {};
}
async function callOpenAICompatibleAPI(endpoint, apiKey, model, messages, temperature = 0.7, maxTokens = 2e3, responseFormat, options) {
  const quirks = options?.quirks || {};
  const buildBody = (msgs) => {
    const body2 = { model, messages: msgs };
    body2[quirks.tokenParam || "max_tokens"] = maxTokens;
    if (!quirks.dropTemperature) body2.temperature = temperature;
    if (responseFormat === "json_object") {
      body2.response_format = { type: "json_object" };
    }
    if (quirks.extraBody) Object.assign(body2, quirks.extraBody);
    return body2;
  };
  const body = buildBody(messages);
  if (options?.tools && options.tools.length > 0) {
    body.tools = options.tools;
    body.tool_choice = "auto";
  }
  let response;
  try {
    response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${apiKey}`
      },
      body: JSON.stringify(body)
    });
  } catch (err) {
    const host = endpoint ? new URL(endpoint).hostname : "\u672A\u77E5\u670D\u52A1";
    const reason = err.cause?.code || err.message || "\u672A\u77E5\u9519\u8BEF";
    throw new Error(`\u65E0\u6CD5\u8FDE\u63A5 ${host}\uFF08${reason}\uFF09\u3002
\u8BF7\u68C0\u67E5\uFF1A1) \u7F51\u7EDC\u662F\u5426\u6B63\u5E38 2) \u662F\u5426\u9700\u8981\u914D\u7F6E\u4EE3\u7406 3) API Key \u662F\u5426\u6B63\u786E`);
  }
  if (!response.ok) {
    const text = await response.text();
    let tip = "";
    if (response.status === 401 || response.status === 403) {
      tip = "\uFF08\u8BF7\u68C0\u67E5 API Key \u662F\u5426\u6B63\u786E\uFF0C\u662F\u5426\u4E3A\u5F53\u524D\u670D\u52A1\u5546\u7684\u5BC6\u94A5\uFF09";
    } else if (response.status === 404) {
      tip = "\uFF08\u6A21\u578B\u540D\u79F0\u53EF\u80FD\u4E0D\u6B63\u786E\uFF0C\u8BF7\u68C0\u67E5\u8BBE\u7F6E\uFF09";
    } else if (response.status === 429) {
      tip = "\uFF08\u8BF7\u6C42\u8FC7\u4E8E\u9891\u7E41\uFF0C\u8BF7\u7A0D\u540E\u91CD\u8BD5\uFF09";
    }
    throw new Error(`API \u9519\u8BEF ${response.status}: ${text.slice(0, 200)}${tip}`);
  }
  const data = await response.json();
  if (data.error) {
    throw new Error(data.error.message || "\u672A\u77E5 API \u9519\u8BEF");
  }
  const choice = data.choices?.[0];
  const msg = choice?.message;
  if (msg?.tool_calls && options?.enableSearch) {
    const toolResults = [];
    for (const tc of msg.tool_calls) {
      if (tc.function?.name === "web_search") {
        try {
          const args = JSON.parse(tc.function.arguments);
          const searchResult = await executeWebSearch(args.query);
          toolResults.push({
            role: "tool",
            tool_call_id: tc.id,
            content: searchResult || `\u641C\u7D22 "${args.query}" \u65E0\u7ED3\u679C`
          });
        } catch {
          toolResults.push({ role: "tool", tool_call_id: tc.id, content: "\u641C\u7D22\u6267\u884C\u5931\u8D25" });
        }
      }
    }
    if (toolResults.length > 0) {
      const followUpMessages = [
        ...messages,
        msg,
        ...toolResults
      ];
      const followUpBody = buildBody(followUpMessages);
      const resp2 = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${apiKey}`
        },
        body: JSON.stringify(followUpBody)
      });
      if (resp2.ok) {
        const data2 = await resp2.json();
        return data2.choices?.[0]?.message?.content?.trim() || "";
      }
    }
  }
  return msg?.content?.trim() || "";
}

